begin;
alter table public.organizations add column if not exists created_by uuid references auth.users(id);create index if not exists organizations_created_by_idx on public.organizations(created_by);
create policy organizations_self_insert on public.organizations for insert to authenticated with check((select auth.uid())=created_by and type<>'platform');
create policy org_members_creator_insert on public.organization_members for insert to authenticated with check(user_id=(select auth.uid()) and role in('seller_admin','investor_admin','advisor','broker','legal_reviewer','external_reviewer') and exists(select 1 from public.organizations o where o.id=organization_id and o.created_by=(select auth.uid())));
drop function if exists public.create_organization(org_type,text,text,char);
create or replace function public.create_organization(p_type org_type,p_legal_name text,p_display_name text,p_country_code char(2)) returns uuid language plpgsql security invoker set search_path=public,pg_catalog as $$ declare v_user uuid:=(select auth.uid());v_org uuid;v_role member_role;begin if v_user is null then raise exception 'authentication_required';end if;if p_type='platform' then raise exception 'platform_organization_not_user_creatable';end if;if nullif(trim(p_display_name),'') is null then raise exception 'display_name_required';end if;v_role:=case p_type when 'seller' then 'seller_admin'::member_role when 'investor' then 'investor_admin'::member_role when 'advisor' then 'advisor'::member_role when 'broker' then 'broker'::member_role when 'legal' then 'legal_reviewer'::member_role when 'service_provider' then 'external_reviewer'::member_role end;insert into public.organizations(type,legal_name,display_name,country_code,created_by) values(p_type,coalesce(nullif(trim(p_legal_name),''),trim(p_display_name)),trim(p_display_name),upper(p_country_code),v_user) returning id into v_org;insert into public.organization_members(organization_id,user_id,role) values(v_org,v_user,v_role);return v_org;end;$$;
revoke all on function public.create_organization(org_type,text,text,char) from public,anon;grant execute on function public.create_organization(org_type,text,text,char) to authenticated;
commit;